class Solution:
    def generateParenthesis(self, n: int) -> List[str]:
        res = []
        def backtrack(open_c, close_c, cur):
            if open_c == close_c == n:
                res.append("".join(cur))
                return
            if open_c < n:
                cur.append("(")
                backtrack(open_c + 1, close_c, cur)
                cur.pop()
            if close_c < open_c:
                cur.append(")")
                backtrack(open_c, close_c + 1, cur)
                cur.pop()
        backtrack(0, 0, [])
        return res

