function generateParenthesis(n) {
    const res = [];
    function backtrack(openC, closeC, cur) {
        if (openC === n && closeC === n) {
            res.push(cur.join(""));
            return;
        }
        if (openC < n) {
            cur.push("(");
            backtrack(openC + 1, closeC, cur);
            cur.pop();
        }
        if (closeC < openC) {
            cur.push(")");
            backtrack(openC, closeC + 1, cur);
            cur.pop();
        }
    }
    backtrack(0, 0, []);
    return res;
}
